* { box-sizing: border-box; }
[hidden] { display: none !important; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color: #1f2933;
  background: #f5f7fa;
}

header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem 2rem;
  padding: 0.75rem 1.5rem;
  background: #243b53;
  color: #fff;
}
header h1 { margin: 0; font-size: 1.4rem; }
nav { display: flex; gap: 0.5rem; }
nav a {
  color: #d9e2ec;
  text-decoration: none;
  padding: 0.35rem 0.75rem;
  border-radius: 4px;
}
nav a.active, nav a:hover { background: #486581; color: #fff; }
.balance { margin-left: auto; font-weight: 600; }

main { max-width: 960px; margin: 0 auto; padding: 1rem 1.5rem 3rem; }

.form, .toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 0.75rem;
  margin-bottom: 1rem;
}
.form label, .toolbar label { display: flex; flex-direction: column; font-size: 0.85rem; gap: 0.2rem; }
.toolbar label.file { flex-direction: row; align-items: center; gap: 0.4rem; }

input, select, button { font: inherit; padding: 0.35rem 0.5rem; }
input, select { border: 1px solid #bcccdc; border-radius: 4px; background: #fff; }
button {
  border: 1px solid #334e68;
  border-radius: 4px;
  background: #334e68;
  color: #fff;
  cursor: pointer;
}
button:disabled { opacity: 0.4; cursor: default; }
button.delete { background: #fff; color: #ba2525; border-color: #ba2525; padding: 0.15rem 0.5rem; }

table.grid { width: 100%; border-collapse: collapse; table-layout: fixed; background: #fff; }
table.grid.head { margin-bottom: 0; }
table.grid th, table.grid td { padding: 0.45rem 0.6rem; text-align: left; border-bottom: 1px solid #e4e7eb; overflow-wrap: anywhere; }
table.grid th { background: #e4e7eb; font-size: 0.85rem; }
#sort-amount { cursor: pointer; user-select: none; }

/* Transactions columns */
#list td:nth-child(1), .head:not(.budgets-grid):not(.report-grid) th:nth-child(1) { width: 18%; }
#list td:nth-child(3), .head:not(.budgets-grid):not(.report-grid) th:nth-child(3) { width: 16%; text-align: right; }
#list td:nth-child(4), .head:not(.budgets-grid):not(.report-grid) th:nth-child(4) { width: 18%; }
#list td:nth-child(5), .head:not(.budgets-grid):not(.report-grid) th:nth-child(5) { width: 10%; text-align: right; }

.budgets-grid td:nth-child(4), .budgets-grid th:nth-child(4) { width: 10%; text-align: right; }
.report-grid td:nth-child(2), .report-grid th:nth-child(2) { text-align: right; }

.neg { color: #ba2525; }
.pos { color: #207227; }
#budgets tr.over td { background: #ffe3e3; color: #8a1c1c; font-weight: 600; }

#chart { display: block; margin-top: 1rem; max-width: 100%; background: #fff; border: 1px solid #e4e7eb; }

